<div class="modal fade pa-modal" id="formModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><small id="formKicker">NUEVA ORDEN</small><h5 class="modal-title mb-0" id="formTitle"><i class="fas fa-file-signature mr-2"></i>Generar OT de Plan de Acción</h5></div><button class="close text-white" data-dismiss="modal">&times;</button></div><div class="modal-body"><form id="paForm"><input type="hidden" id="paDocEntry"><input type="hidden" id="paOrigin"><input type="hidden" id="paItem"><div class="pa-form-section"><h6><i class="fas fa-link mr-1"></i>Origen y plan identificado</h6><div class="row"><div class="col-md-3"><label>OT origen</label><input id="paOriginLabel" class="form-control" readonly></div><div class="col-md-9"><label>Equipo de la OT origen</label><div id="paItemLabel" class="form-control bg-light"><i class="fas fa-link text-info mr-1"></i>Se cargará desde la OT origen</div><small class="text-muted">El equipo se hereda automáticamente y no puede modificarse.</small></div></div><label class="mt-3">Plan de acción definido en la OT</label><div class="pa-plan-box" id="paPlanText">-</div></div><div class="pa-form-section"><h6><i class="fas fa-tools mr-1"></i>Datos de la orden de Plan de Acción</h6><div class="row"><div class="col-md-4"><div class="form-group"><label>Tipo de mantenimiento *</label><select id="paType" class="form-control" required></select></div></div><div class="col-md-4"><div class="form-group"><label>Técnico responsable</label><select id="paTech" class="form-control"></select></div></div><div class="col-md-4"><div class="form-group"><label>Detalle SVT</label><input id="paSvt" class="form-control" maxlength="150"></div></div><div class="col-md-3"><div class="form-group"><label>Fecha inicio *</label><input type="date" id="paStart" class="form-control" required></div></div><div class="col-md-3"><div class="form-group"><label>Fecha fin</label><input type="date" id="paEnd" class="form-control"></div></div><div class="col-md-3"><div class="form-group"><label>Hora inicio</label><input type="time" id="paHStart" class="form-control"></div></div><div class="col-md-3"><div class="form-group"><label>Hora fin</label><input type="time" id="paHEnd" class="form-control"></div></div><div class="col-md-8"><div class="form-group"><label>Título de la OT</label><input id="paTitle" class="form-control" maxlength="150"></div></div><div class="col-md-4"><div class="form-group"><label>Estado</label><select id="paStatus" class="form-control"><option>ABIERTO</option><option>EN PROCESO</option><option>CERRADO</option><option>ANULADO</option></select></div></div><div class="col-12"><div class="form-group"><label>Trabajo a realizar / realizado *</label><textarea id="paWork" class="form-control" rows="4" required></textarea></div></div><div class="col-12"><div class="form-group mb-0"><label>Observaciones</label><textarea id="paObs" class="form-control" rows="3"></textarea></div></div></div></div></form></div><div class="modal-footer"><span class="text-muted small mr-auto"><i class="fas fa-database mr-1"></i>Se guardará en SAP y conservará la relación con la OT origen.</span><button class="btn btn-secondary" data-dismiss="modal">Cancelar</button><button class="btn btn-success font-weight-bold" id="btnSave"><i class="fas fa-save mr-1"></i>Guardar orden</button></div></div></div></div>
<script>
window.addEventListener('load', function () {
(function(){
var API='<?= rtrim(BASE_URL,'/') ?>/api/mantenimientos/plan_accion_ot.php',canEdit=<?= $canEdit?'true':'false' ?>,rows=[],pending=[],equipos=[],tipos=[],tecnicos=[];
function e(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function date(v){var s=String(v||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:'';}function time(v){var n=parseInt(v,10);if(!n)return '';return String(Math.floor(n/100)).padStart(2,'0')+':'+String(n%100).padStart(2,'0');}
function req(url,opt){opt=opt||{};if(!opt.method||String(opt.method).toUpperCase()==='GET')opt.cache='no-store';return fetch(url,opt).then(function(r){return r.json().then(function(j){if(!r.ok||j.error)throw Object.assign(new Error(j.error||'Error de comunicación.'),{config:j.config||null,status:r.status});return j;});});}
function showConfig(err){if(!err||err.status!==503)return;$('#paConfig').html('<b><i class="fas fa-cogs mr-1"></i>Configuración SAP pendiente:</b> '+e(err.message)).show();}
function badge(s){var k=String(s||'ABIERTO').toLowerCase().replace(/\s+/g,'-');return '<span class="pa-status '+e(k)+'">'+e(s||'ABIERTO')+'</span>';}
function loadCatalogs(){return Promise.all([fetch('<?= rtrim(BASE_URL,'/') ?>/api/mantenimientos/get_equipos.php?modo=crud&limit=10000').then(r=>r.json()),fetch('<?= rtrim(BASE_URL,'/') ?>/api/mantenimientos/get_tipomant.php').then(r=>r.json()),fetch('<?= rtrim(BASE_URL,'/') ?>/api/mantenimientos/get_tecnicos.php').then(r=>r.json())]).then(function(all){equipos=all[0].data||[];tipos=Array.isArray(all[1])?all[1]:(all[1].data||[]);tecnicos=Array.isArray(all[2])?all[2]:(all[2].data||[]);});}
function fill(id,data,value,label){var el=document.getElementById(id);el.innerHTML='<option value="">Seleccione...</option>'+data.map(function(x){var v=x.Code||x.ItemCode||x.Name||'';return '<option value="'+e(v)+'"'+(String(v)===String(value||'')?' selected':'')+'>'+e(label(x))+'</option>';}).join('');}
function load(){req(API+'?action=list').then(function(j){rows=j.rows||[];render();$('#paConfig').hide();}).catch(function(x){showConfig(x);$('#paBody').html('<tr><td colspan="9" class="pa-empty text-danger">'+e(x.message)+'</td></tr>');});loadPending(false);}
function render(){var body=$('#paBody');if(!rows.length){body.html('<tr><td colspan="9" class="pa-empty">No existen órdenes de Plan de Acción generadas.</td></tr>');}else body.html(rows.map(function(r){return '<tr><td><b>PA-'+e(r.DocNum)+'</b></td><td><span class="pa-origin">OT-'+e(r.U_OTOrigenDN)+'</span><br><small>DocEntry '+e(r.U_OTOrigenDE)+'</small></td><td><b>'+e(r.U_ItemCode)+'</b><br><small>'+e(r.ItemName)+'</small></td><td>'+e(r.U_TituFor||'-')+'</td><td>'+e(r.TecnicoName||r.U_Tecnico||'-')+'</td><td>'+e(date(r.U_FechaInicio)||'-')+'</td><td>'+e(date(r.U_FechaFin)||'-')+'</td><td>'+badge(r.U_EstadoPlan)+'</td><td>'+(canEdit?'<button class="btn btn-sm btn-outline-info pa-edit" data-id="'+e(r.DocEntry)+'"><i class="fas fa-edit"></i></button>':'-')+'</td></tr>';}).join(''));$('#kTotal').text(rows.length);$('#kOpen').text(rows.filter(r=>['ABIERTO','EN PROCESO'].includes(String(r.U_EstadoPlan))).length);$('#kClosed').text(rows.filter(r=>String(r.U_EstadoPlan)==='CERRADO').length);}
function loadPending(open){req(API+'?action=pending').then(function(j){pending=j.rows||[];$('#pendingBadge,#kPending').text(pending.length);renderPending();if(open)$('#pendingModal').modal('show');}).catch(function(x){showConfig(x);pending=[];$('#pendingBadge,#kPending').text(0);if(open)Swal.fire('Configuración pendiente',x.message,'warning');});}
function renderPending(){var b=$('#pendingBody');if(!pending.length){b.addClass('pa-empty').html('<i class="fas fa-check-circle fa-2x text-success mb-2"></i><div>No hay planes pendientes de generar.</div>');return;}b.removeClass('pa-empty').html(pending.map(function(r){return '<div class="pa-pending-card"><div><b>OT-'+e(r.DocNum)+'</b><br><small>'+e(date(r.U_FechaInicio))+'</small></div><div><b>'+e(r.U_ItemCode)+'</b><br><small>'+e(r.ItemName)+'</small></div><div class="pa-pending-plan">'+e(r.U_PlanAccion)+'</div><button class="btn btn-warning btn-sm font-weight-bold pa-generate" data-id="'+e(r.DocEntry)+'"><i class="fas fa-arrow-right mr-1"></i>Generar</button></div>';}).join(''));}
function setForm(source,child){child=child||{};var item=source.U_ItemCode||'';$('#paDocEntry').val(child.DocEntry||'');$('#paOrigin').val(source.DocEntry);$('#paOriginLabel').val('OT-'+source.DocNum+' / DocEntry '+source.DocEntry);$('#paItem').val(item);$('#paItemLabel').html('<b>'+e(item)+'</b>'+(source.ItemName?' - '+e(source.ItemName):''));$('#paPlanText').text(source.U_PlanAccion||'-');fill('paType',tipos,child.U_TipoMant||source.U_TipoMant,x=>(x.Code||'')+' - '+(x.Name||''));fill('paTech',tecnicos,child.U_Tecnico||source.U_Tecnico,x=>(x.Code||'')+' - '+(x.Name||''));$('#paSvt').val(child.U_DetalleSVT||source.U_DetalleSVT||'');$('#paStart').val(date(child.U_FechaInicio)||date(source.U_FechaInicio)||new Date().toISOString().slice(0,10));$('#paEnd').val(date(child.U_FechaFin));$('#paHStart').val(time(child.U_Hora_Ini)||time(source.U_Hora_Ini));$('#paHEnd').val(time(child.U_Hora_Fin)||time(source.U_Hora_Fin));$('#paTitle').val(child.U_TituFor||('Plan de acción - OT '+source.DocNum));$('#paWork').val(child.U_TrabajoRealizado||source.U_PlanAccion||'');$('#paObs').val(child.U_Observacion||'');$('#paStatus').val(child.U_EstadoPlan||'ABIERTO');$('#formKicker').text(child.DocEntry?'EDITAR ORDEN PA-'+child.DocNum:'NUEVA ORDEN VINCULADA');$('#formModal').modal('show');}
function openSource(id){Promise.all([loadCatalogs(),req(API+'?action=source&docentry='+encodeURIComponent(id))]).then(x=>setForm(x[1].row,null)).catch(x=>{showConfig(x);Swal.fire('No se pudo abrir',x.message,'error');});}
function edit(id){Promise.all([loadCatalogs(),req(API+'?action=get&docentry='+encodeURIComponent(id))]).then(function(x){var child=x[1].row;return req(API+'?action=source&docentry='+encodeURIComponent(child.U_OTOrigenDE)).then(s=>setForm(s.row,child));}).catch(x=>Swal.fire('No se pudo abrir',x.message,'error'));}
function save(){var data={action:'save_order',docentry:Number($('#paDocEntry').val()||0),origen_docentry:Number($('#paOrigin').val()),itemcode:$('#paItem').val(),tipomant:$('#paType').val(),tecnico:$('#paTech').val(),detalle_svt:$('#paSvt').val(),fechainicio:$('#paStart').val(),fechafin:$('#paEnd').val(),horainicio:$('#paHStart').val(),horafin:$('#paHEnd').val(),titulo:$('#paTitle').val(),trabajo:$('#paWork').val(),observacion:$('#paObs').val(),estado:$('#paStatus').val()};var btn=$('#btnSave'),old=btn.html();btn.prop('disabled',true).html('<i class="fas fa-spinner fa-spin mr-1"></i>Guardando en SAP');req(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).then(function(){ $('#formModal,#pendingModal').modal('hide');Swal.fire({icon:'success',title:'Orden de Plan de Acción guardada',timer:1600,showConfirmButton:false});load();}).catch(x=>Swal.fire('No se pudo guardar',x.message,'error')).finally(()=>btn.prop('disabled',false).html(old));}
$(document).on('click','#btnPending',()=>loadPending(true));$(document).on('click','#btnReload',load);$(document).on('click','.pa-generate',function(){openSource(this.dataset.id);});$(document).on('click','.pa-edit',function(){edit(this.dataset.id);});$(document).on('click','#btnSave',save);load();
})();
});
</script>
<?php include_once __DIR__.'/../../layouts/footer.php'; ?>
